    if not rows:
        print(run, "no G016 3h lines"); continue
    print("== %s: %d lines, look-ahead %d, max %d; last height %d" % (run.rstrip("/").split("/")[-1], len(rows), rows[0]["la"], rows[0]["max"], rows[-1]["h"]))
    print("%-3s %-17s %7s %8s %8s %8s %8s %7s %7s %6s %7s %8s" % ("win", "heights", "calls", "prune_s", "pass_s", "advised", "advP", "del", "del_ov", "res", "res%", "ms/call"))
    zero = {k: 0 for k in KEYS}

    def at(h):
        prev = [r for r in rows if r["h"] <= h]
        return prev[-1] if prev else zero
    tot = None
    for k in range(7):
        lo, hi = START + 1 + W * k, START + W * (k + 1)
        a = at(lo - 1) if k else zero
        b = at(hi) if k < 6 else rows[-1]
        d = {x: b[x] - a[x] for x in ["calls", "prune_s", "pass_s", "adv", "advP", "del", "delov", "res"]}
        pct = "%.1f" % (100.0 * d["res"] / d["delov"]) if d["delov"] else "na"
        msc = "%.1f" % (1000.0 * d["prune_s"] / d["calls"]) if d["calls"] else "na"
        print("%-3d %-17s %7d %8.2f %8.2f %8d %8d %7d %7d %6d %7s %8s" % (k, "%d-%d" % (a["h"] if k else START, b["h"]), d["calls"], d["prune_s"], d["pass_s"], d["adv"], d["advP"], d["del"], d["delov"], d["res"], pct, msc))
    r = rows[-1]
    print("all  calls %d, prune %.2f s, pre-pass %.2f s; advised %d records (%d + %d first pages); deleted %d, %d overflow, %d resident (%s%%); stops %d look-ahead, %d max" % (
        r["calls"], r["prune_s"], r["pass_s"], r["adv"], r["advP"], r["advD"], r["del"], r["delov"], r["res"],
        "%.1f" % (100.0 * r["res"] / r["delov"]) if r["delov"] else "na", r["la_stops"], r["max_stops"]))
